insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1700.svg', '1752-02-29', '1885-11-29', 'Dynastie Konbaung', 'Konbaung dynasty', 'Bannière de la dernière dynastie royale birmane, ornée du paon, emblème des rois ; le roi Thibaw est déposé par les Britanniques en 1885.', 'Banner of the last Burmese royal dynasty, bearing the peacock, emblem of the kings; King Thibaw was deposed by the British in 1885.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1939.svg', '1937-04-01', '1948-01-04', 'Birmanie britannique', 'British Burma', 'Séparée de l''Inde britannique en 1937, la Birmanie reçoit un Blue Ensign chargé d''un paon.', 'Separated from British India in 1937, Burma received a Blue Ensign bearing a peacock.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1943.svg', '1943-08-01', '1945-03-27', 'État de Birmanie (occupation japonaise)', 'State of Burma (Japanese occupation)', 'Drapeau de l''État de Birmanie de Ba Maw, proclamé sous l''occupation japonaise : tricolore jaune-vert-rouge au paon.', 'Flag of Ba Maw''s State of Burma, proclaimed under Japanese occupation: a yellow-green-red tricolour with a peacock.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('mm', '/flags/history/mm-1948.svg', '1948-01-04', '1974-01-03', 'Union de Birmanie', 'Union of Burma', 'À l''indépendance, le drapeau rouge porte au canton bleu une grande étoile blanche entourée de cinq petites, pour les principaux peuples de l''Union.', 'At independence the red flag carried, in a blue canton, a large white star ringed by five small ones for the Union''s main peoples.');
